### 三、修复阶段设计

#### 选材阶段（fix-plan.logic.js 扩展）

```js
selectFixablePrompts(report) {
  if (!report.dimensions?.prompts?.fixable) return {skills: []}

  const candidates = report.dimensions.prompts.llmAnalysis.skills
    .filter(s => s.improvements.length > 0)

  return {
    skills: candidates.map(s => ({
      file: s.file,
      improvements: s.improvements.slice(0, 5) // 最多 5 项改进
    }))
  }
}

selectFixableComments(report) {
  if (!report.dimensions?.comments?.fixable) return {files: []}

  const candidates = report.dimensions.comments.llmAnalysis.files
    .concat(
      report.dimensions.comments.issues
        .filter(i => i.code === 'C1_EXPORT_UNCOMMENTED')
        .map(i => ({file: i.file, actions: [{type:'add', line: i.lineNo}]}))
    )

  return {
    files: dedupByFile(candidates)
  }
}
```

#### 应用阶段（fix-prompts.js / fix-comments.js）

**维度② applyPromptsFix**：

```js
applyPromptsFix(projectDir, plan, signal) {
  // plan.skills = [{file, improvements: [...]}, ...]

  return runSequential(plan.skills, async (skillEntry, idx) => {
    const {file, improvements} = skillEntry
    const content = fs.readFileSync(file, 'utf-8')
    const {frontmatter, body} = parseSkillFrontmatter(content)

    // 逐个应用改进建议
    let modified = {frontmatter, body}
    for (const improvement of improvements) {
      if (improvement.type === 'description') {
        // LLM 生成的新 description
        modified.frontmatter.description = improvement.newValue
      } else if (improvement.type === 'trigger') {
        modified.frontmatter.trigger = improvement.newValue
      } else if (improvement.type === 'add_section') {
        // 补充参数段落、示例等
        modified.body = injectSection(modified.body, improvement)
      }
    }

    const newContent = reconstructSkillFile(modified)
    fs.writeFileSync(file, newContent, 'utf-8')

    emitSSE({
      type: 'progress',
      phase: 'prompts',
      current: idx + 1,
      total: plan.skills.length,
      file
    })

    return {file, status: 'done', changes: improvements.length}
  }, {signal})
}
```

**维度⑤ applyCommentsFix**：

```js
applyCommentsFix(projectDir, plan, signal) {
  // plan.files = [{file, actions: [{type:'delete|add|improve', ...}]}, ...]

  return runSequential(plan.files, async (fileEntry, idx) => {
    const {file, actions} = fileEntry
    const lines = fs.readFileSync(file, 'utf-8').split('\n')

    // 按行号倒序处理（避免行号漂移）
    const sortedActions = actions.sort((a, b) => (b.line || Infinity) - (a.line || Infinity))

    for (const action of sortedActions) {
      if (action.type === 'add') {
        // 在指定行上方插入块注释
        const comment = formatBlockComment(action.suggestion)
        lines.splice(action.line - 1, 0, comment)
      } else if (action.type === 'delete') {
        // 删除指定行的注释
        lines.splice(action.line - 1, 1)
      } else if (action.type === 'improve') {
        // 改进指定行的注释措辞
        lines[action.line - 1] = action.suggestion
      }
    }

    fs.writeFileSync(file, lines.join('\n'), 'utf-8')

    emitSSE({
      type: 'progress',
      phase: 'comments',
      current: idx + 1,
      total: plan.files.length,
      file
    })

    return {file, status: 'done', changes: actions.length}
  }, {signal})
}
```

