### 四、备份和还原隔离

```js
// backup.js 扩展

createBackup(entries, dimension) {
  // entries = [{file, action:'created|modified'}]
  // dimension = 'prompts' | 'comments'

  const backupKey = `${sessionId}:${dimension}`
  const snapshot = {
    dimension,
    timestamp: Date.now(),
    entries: entries.map(e => ({
      file: e.file,
      content: fs.readFileSync(e.file, 'utf-8'),
      mtime: fs.statSync(e.file).mtime
    }))
  }

  store.optimize.setSnapshot(backupKey, snapshot)
}

rollback(dimension) {
  // dimension = 'prompts' | 'comments' | 'all'

  const backupKey = `${sessionId}:${dimension === 'all' ? '*' : dimension}`
  const snapshots = store.optimize.getSnapshots(backupKey)

  for (const snapshot of snapshots) {
    for (const entry of snapshot.entries) {
      fs.writeFileSync(entry.file, entry.content, 'utf-8')
      fs.utimesSync(entry.file, entry.mtime, entry.mtime) // 还原 mtime
    }
  }
}
```

