### 2. 交互流程

**用户操作序列：**
1. 打开设置 → 切到「会话清理」tab
2. 看到当前目录、总会话数
3. 选择快捷选项之一（单选） → 实时显示该条件下待删数量 `(X 个会话)`
4. 可选：展开「自定义日期范围」→ 选日期 → 点「计算数量」更新待删数
5. 确认「将删除：X 个会话」
6. 点「清理会话」→ 弹 `confirmDialog` 二次确认
7. 确认后 → 后台执行删除 → toast 显示 `已删除 8 个会话` → tab 重新加载统计

### 3. 前端逻辑（`public/js/settings-panel.js` 新增）

```javascript
// 会话清理初始化
async function loadCleanupTab() {
  const cwd = /* 从设置页获取当前工作目录 */;
  const totalCount = await fetchCleanupStats(cwd, { all: true });
  $('#cleanupTotalCount').textContent = totalCount;
  $('#cleanupCwd').textContent = cwd || '(默认)';

  // 计算各快捷选项的会话数
  for (const days of [7, 14, 30, 90]) {
    const count = await fetchCleanupStats(cwd, { days });
    $(`#count${days}`).textContent = `(${count})`;
  }
}

// 快捷选项变化 → 更新待删数
document.querySelectorAll('input[name="cleanupRange"]').forEach(radio => {
  radio.addEventListener('change', async (e) => {
    const days = e.target.value;
    const count = await fetchCleanupStats(/* cwd */, { days });
    $('#cleanupWillDelete').textContent = `将删除：${count} 个会话`;
    $('#cleanupBtn').disabled = count === 0;
  });
});

// 自定义日期计算
$('#cleanupCustomCalc').addEventListener('click', async () => {
  const from = $('#cleanupDateFrom').value;
  const to = $('#cleanupDateTo').value;
  if (!from || !to) return toast('请选择完整的日期范围');
  const count = await fetchCleanupStats(/* cwd */, { from, to });
  $('#cleanupWillDelete').textContent = `将删除：${count} 个会话`;
});

// 清理按钮
$('#cleanupBtn').addEventListener('click', async () => {
  const confirmed = await confirmDialog({
    title: '删除会话',
    message: '确定要删除这些会话吗？删除后无法恢复。',
    danger: true,
  });
  if (!confirmed) return;

  // 执行删除
  const params = getCleanupParams(); // 获取当前选择的参数
  try {
    const result = await fetch('/api/history/cleanup', {
      method: 'POST',
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify(params),
    }).then(r => r.json());

    if (result.error) return toast(`清理失败：${result.error}`);
    toast(`已删除 ${result.deletedCount} 个会话`);

    // 重新加载统计
    await loadCleanupTab();
  } catch (e) {
    toast(`清理出错：${e.message}`);
  }
});

// 辅助函数：获取快捷/自定义参数
function getCleanupParams() {
  if ($('#customDateDetails').open) {
    return {
      cwd: /* 当前 cwd */,
      from: $('#cleanupDateFrom').value,
      to: $('#cleanupDateTo').value,
    };
  } else {
    return {
      cwd: /* 当前 cwd */,
      days: document.querySelector('input[name="cleanupRange"]:checked').value,
    };
  }
}

// 辅助函数：计数（不删除）
