```javascript
/**
 * 预计算待删会话数（无副作用）
 * @param {string} dir - 历史目录路径
 * @param {object} options - { range?: number, fromDate?: string, toDate?: string }
 * @returns {Promise<{ willDeleteCount: number, oldestSession?: string, newestSession?: string }>}
 */
export async function previewCleanup(dir, options = {}) {
  try {
    const files = await fs.promises.readdir(dir, { withFileTypes: true });
    const now = Date.now();
    let sessions = [];

    for (const file of files) {
      if (!file.isFile() || !file.name.endsWith('.jsonl')) continue;
      const fullPath = path.join(dir, file.name);
      const stat = await fs.promises.stat(fullPath);
      sessions.push({
        name: file.name,
        mtimeMs: stat.mtimeMs,
      });
    }

    // 按时间筛选
    let filtered = sessions;
    if (options.range) {
      const cutoffTime = now - options.range * 24 * 60 * 60 * 1000;
      filtered = sessions.filter((s) => s.mtimeMs < cutoffTime);
    } else if (options.fromDate && options.toDate) {
      const fromMs = new Date(options.fromDate).getTime();
      const toMs = new Date(options.toDate).getTime();
      filtered = sessions.filter((s) => s.mtimeMs >= fromMs && s.mtimeMs <= toMs);
    }

    const oldest = filtered.length > 0 ? new Date(Math.min(...filtered.map((s) => s.mtimeMs))).toISOString() : null;
    const newest = filtered.length > 0 ? new Date(Math.max(...filtered.map((s) => s.mtimeMs))).toISOString() : null;

    return {
      willDeleteCount: filtered.length,
      oldestSession: oldest,
      newestSession: newest,
    };
  } catch (e) {
    if (e.code === 'ENOENT') return { willDeleteCount: 0 };
    throw e;
  }
}
```

