/**
 * 物理删除会话文件
 * @param {string} dir - 历史目录路径
 * @param {object} options - { range?: number, fromDate?: string, toDate?: string }
 * @returns {Promise<{ deletedCount: number, freedBytes: number }>}
 */
export async function deleteHistorySessions(dir, options = {}) {
  const preview = await previewCleanup(dir, options);
  const willDeleteCount = preview.willDeleteCount;

  if (willDeleteCount === 0) {
    return { deletedCount: 0, freedBytes: 0 };
  }

  try {
    const files = await fs.promises.readdir(dir, { withFileTypes: true });
    const now = Date.now();
    let deletedCount = 0;
    let freedBytes = 0;

    for (const file of files) {
      if (!file.isFile() || !file.name.endsWith('.jsonl')) continue;
      const fullPath = path.join(dir, file.name);
      const stat = await fs.promises.stat(fullPath);

      let shouldDelete = false;
      if (options.range) {
        const cutoffTime = now - options.range * 24 * 60 * 60 * 1000;
        shouldDelete = stat.mtimeMs < cutoffTime;
      } else if (options.fromDate && options.toDate) {
        const fromMs = new Date(options.fromDate).getTime();
        const toMs = new Date(options.toDate).getTime();
        shouldDelete = stat.mtimeMs >= fromMs && stat.mtimeMs <= toMs;
      }

      if (shouldDelete) {
        await fs.promises.unlink(fullPath);
        deletedCount++;
        freedBytes += stat.size;
      }
    }

    return { deletedCount, freedBytes };
  } catch (e) {
    if (e.code === 'ENOENT') return { deletedCount: 0, freedBytes: 0 };
    throw e;
  }
}
